package cn.pawday.integration;
import cn.pawday.common.Api;
import cn.pawday.identity.AccessGuard;
import static cn.pawday.publishing.PublishingSupport.*;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/merchant/stores/{store_id}/integration-connections")
public class IntegrationInventoryController {
 private final IntegrationInventoryService service;private final AccessGuard guard;
 public IntegrationInventoryController(IntegrationInventoryService service,AccessGuard guard){this.service=service;this.guard=guard;}
 @GetMapping Object list(@PathVariable String store_id,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){return paged(service.connections(guard.actor(),id(store_id),cursor(cursor),limit),limit,r);}
 @PostMapping Object create(@PathVariable String store_id,@RequestBody Map<String,Object>b,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Reverify-Token",required=false)String proof,HttpServletRequest r){return Api.ok(service.create(guard.actor(),id(store_id),b,key,proof,r),r);}
 @PutMapping("/{connection_id}/state") Object state(@PathVariable String store_id,@PathVariable String connection_id,@RequestBody Map<String,Object>b,@RequestHeader(value="If-Match",required=false)String match,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Reverify-Token",required=false)String proof,HttpServletRequest r){return Api.ok(service.state(guard.actor(),id(store_id),id(connection_id),b,match,key,proof,r),r);}
 @GetMapping("/{connection_id}/mappings") Object mappings(@PathVariable String store_id,@PathVariable String connection_id,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){return paged(service.mappings(guard.actor(),id(store_id),id(connection_id),cursor(cursor),limit),limit,r);}
 @PostMapping("/{connection_id}/mappings") Object bind(@PathVariable String store_id,@PathVariable String connection_id,@RequestBody Map<String,Object>b,@RequestHeader(value="If-Match",required=false)String match,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Reverify-Token",required=false)String proof,HttpServletRequest r){return Api.ok(service.bind(guard.actor(),id(store_id),id(connection_id),b,match,key,proof,r),r);}
 @PutMapping("/{connection_id}/mappings/{mapping_id}/state") Object retire(@PathVariable String store_id,@PathVariable String connection_id,@PathVariable String mapping_id,@RequestBody Map<String,Object>b,@RequestHeader(value="If-Match",required=false)String match,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Reverify-Token",required=false)String proof,HttpServletRequest r){return Api.ok(service.retire(guard.actor(),id(store_id),id(connection_id),id(mapping_id),b,match,key,proof,r),r);}
 @GetMapping("/{connection_id}/inventory-events") Object events(@PathVariable String store_id,@PathVariable String connection_id,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){return paged(service.events(guard.actor(),id(store_id),id(connection_id),cursor(cursor),limit),limit,r);}
 @PostMapping("/{connection_id}/inventory-events/{event_id}/previews") Object preview(@PathVariable String store_id,@PathVariable String connection_id,@PathVariable String event_id,@RequestBody Map<String,Object>b,@RequestHeader(value="Idempotency-Key",required=false)String key,HttpServletRequest r){return Api.ok(service.preview(guard.actor(),id(store_id),id(connection_id),id(event_id),b,key,r),r);}
 @PostMapping("/{connection_id}/inventory-previews/{preview_id}/apply") Object apply(@PathVariable String store_id,@PathVariable String connection_id,@PathVariable String preview_id,@RequestBody Map<String,Object>b,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Reverify-Token",required=false)String proof,HttpServletRequest r){return Api.ok(service.apply(guard.actor(),id(store_id),id(connection_id),id(preview_id),b,key,proof,r),r);}
 @GetMapping("/{connection_id}/inventory-applications") Object applications(@PathVariable String store_id,@PathVariable String connection_id,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){return paged(service.applications(guard.actor(),id(store_id),id(connection_id),cursor(cursor),limit),limit,r);}
}
